select min(number), max(number), min(placed_at) filter (where number like 'R-1000%') from ordering_order;
\echo '=== O15 fragment "czerniak" -placedAt'
EXPLAIN (ANALYZE, BUFFERS) SELECT o.id, o.number, o.placed_at, o.status, o.email, o.full_name, o.total_gross, o.currency, (SELECT COALESCE(SUM(l.quantity), 0) FROM ordering_order_line l WHERE l.order_id = o.id) AS item_count, o.refund_amount, o.refund_due_at, o.refund_completed_at FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('czerniak') || '%' ORDER BY o.placed_at DESC, o.id DESC LIMIT 26;
\echo '=== O16 fragment "g10000" (only old orders)'
EXPLAIN (ANALYZE, BUFFERS) SELECT o.id, o.number, o.placed_at, o.status, o.email, o.full_name, o.total_gross, o.currency, (SELECT COALESCE(SUM(l.quantity), 0) FROM ordering_order_line l WHERE l.order_id = o.id) AS item_count, o.refund_amount, o.refund_due_at, o.refund_completed_at FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('g10000') || '%' ORDER BY o.placed_at DESC, o.id DESC LIMIT 26;
\echo '=== O17 fragment "example.net" -placedAt'
EXPLAIN (ANALYZE, BUFFERS) SELECT o.id, o.number, o.placed_at, o.status, o.email, o.full_name, o.total_gross, o.currency, (SELECT COALESCE(SUM(l.quantity), 0) FROM ordering_order_line l WHERE l.order_id = o.id) AS item_count, o.refund_amount, o.refund_due_at, o.refund_completed_at FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('.org') || '%' AND o.status='paid' ORDER BY o.placed_at DESC, o.id DESC LIMIT 26;
\echo '=== O18 fragment "ryszard" + status returned'
EXPLAIN (ANALYZE, BUFFERS) SELECT o.id, o.number, o.placed_at, o.status, o.email, o.full_name, o.total_gross, o.currency, (SELECT COALESCE(SUM(l.quantity), 0) FROM ordering_order_line l WHERE l.order_id = o.id) AS item_count, o.refund_amount, o.refund_due_at, o.refund_completed_at FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('ryszard') || '%' AND o.status='returned' ORDER BY o.placed_at DESC, o.id DESC LIMIT 26;
\echo '=== O18c count'
EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM (SELECT 1 FROM ordering_order o WHERE lower(o.number || E'\x1f' || o.email || E'\x1f' || o.full_name) LIKE '%' || lower('ryszard') || '%' AND o.status='returned' LIMIT 10001) bounded;
